{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C73"],
      "claim": "Zalcitabine, a small polar dideoxynucleoside, has absolute oral bioavailability of 86–100% in adults, demonstrating that hydrophilic nucleosides can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Lamivudine, a polar nucleoside analog, has absolute oral bioavailability of 87% in humans, supporting high F for the query's nucleoside-like structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Emtricitabine, a fluorinated cytidine nucleoside analog, has absolute oral bioavailability of 93%, showing that fluorine substitution on a nucleoside base is compatible with high absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C76"],
      "claim": "Isosorbide 5-mononitrate, a small polar polyhydroxylated molecule, has near-complete oral bioavailability (~100%), supporting that high polarity does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cladribine, a purine 2'-deoxynucleoside, has oral bioavailability of ~48%, still above the 20% threshold, indicating purine nucleosides can achieve high label despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Didanosine, an acid-labile dideoxypurine nucleoside, has F as low as 17% under fed conditions, the main nucleoside example below the 20% threshold; this is attributable to acid instability and is not representative of the query's ribosyl 2-amino-6-fluoropurine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High is better supported: highly transferable nucleoside analogues (zalcitabine, lamivudine, emtricitabine, cladribine) show F values well above 20%, and the only sub-20% nucleoside example (didanosine) is an acid-labile dideoxynucleoside unlike the query's ribosyl 2-amino-6-fluoropurine.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "The acid stability and first-pass metabolism of 6-fluoro-2-aminopurine riboside are not directly evidenced.",
    "Some retrieved records are associated with mismatched SMILES in the source data; interpretation relied on the reported compound identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

